PRAGMA foreign_keys = ON;
CREATE TABLE admins (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, price NUMERIC NOT NULL CHECK(price>=0), original_price NUMERIC CHECK(original_price IS NULL OR original_price>=0), currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','CNY')), stock INTEGER NOT NULL DEFAULT 999 CHECK(stock>=0), sales INTEGER NOT NULL DEFAULT 0 CHECK(sales>=0), image_url TEXT, status TEXT NOT NULL DEFAULT 'on_sale' CHECK(status IN ('on_sale','off_sale')), sort_order INTEGER DEFAULT 0, category_id INTEGER NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, description TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_no TEXT UNIQUE NOT NULL, user_id INTEGER, guest_token TEXT, total_amount NUMERIC NOT NULL, currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','CNY')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','delivering','completed','cancelled','refunded')), payment_method_id INTEGER, payment_code TEXT, payment_name TEXT, payment_snapshot TEXT, payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','submitted','confirmed','failed')), payment_reference TEXT, payment_submitted_at TEXT, contact_name TEXT, contact_phone TEXT, shipping_address TEXT, remark TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, product_id INTEGER NOT NULL, product_name TEXT NOT NULL, unit_price NUMERIC NOT NULL, quantity INTEGER NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE chat_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, token TEXT UNIQUE NOT NULL, user_id INTEGER, visitor_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')), admin_last_read_message_id INTEGER NOT NULL DEFAULT 0, last_message_at TEXT DEFAULT CURRENT_TIMESTAMP, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE chat_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, sender TEXT NOT NULL CHECK(sender IN ('visitor','agent','system')), content TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES chat_sessions(id) ON DELETE CASCADE);
CREATE TABLE settings (name TEXT PRIMARY KEY, value TEXT);
CREATE TABLE captcha_challenges (id TEXT PRIMARY KEY, answer_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_methods (id INTEGER PRIMARY KEY AUTOINCREMENT, paytype TEXT UNIQUE NOT NULL, paytypetitle TEXT NOT NULL, ftitle TEXT NOT NULL DEFAULT '', minmoney NUMERIC NOT NULL DEFAULT 100 CHECK(minmoney>=0), maxmoney NUMERIC NOT NULL DEFAULT 50000 CHECK(maxmoney>=minmoney), isonline INTEGER NOT NULL DEFAULT 0 CHECK(isonline IN (0,1)), state INTEGER NOT NULL DEFAULT 1 CHECK(state IN (0,1)), configs TEXT NOT NULL DEFAULT '{}', remark TEXT NOT NULL DEFAULT '', listorder INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_orders_user ON orders(user_id); CREATE INDEX idx_chat_user ON chat_sessions(user_id); CREATE INDEX idx_chat_messages ON chat_messages(session_id,id);
